// Paygate webhook signature handling. See docs/SPEC.md, "Signatures" and "Replays".

import { createHmac, timingSafeEqual } from "node:crypto";

export class SignatureError extends Error {}

export interface SignatureHeader {
  timestamp: number;
  signatures: string[];
}

function parseTimestamp(value: string): number {
  if (!/^\d+$/.test(value) || !Number.isSafeInteger(Number(value))) {
    throw new SignatureError("timestamp must be integer seconds");
  }
  return Number(value);
}

function parseHeader(header: string): { timestamp?: string; signatures: string[] } {
  let timestamp: string | undefined;
  const signatures: string[] = [];
  for (const part of header.split(",")) {
    const idx = part.indexOf("=");
    if (idx <= 0) throw new SignatureError(`malformed signature element ${JSON.stringify(part)}`);
    const key = part.slice(0, idx).trim();
    const value = part.slice(idx + 1).trim();
    if (key === "t") {
      if (timestamp !== undefined) throw new SignatureError("multiple timestamps");
      parseTimestamp(value);
      timestamp = value;
    } else if (key === "v1") {
      if (!/^[0-9a-f]{64}$/.test(value)) throw new SignatureError("v1 signature must be 64 hex chars");
      signatures.push(value);
    }
    // Unknown signature versions are ignored.
  }
  if (signatures.length === 0) throw new SignatureError("no v1 signature");
  return { timestamp, signatures };
}

// Paygate-Signature: t=1731920000,v1=5257a869...,v1=9f1c0d2e...
export function parseSignatureHeader(header: string): SignatureHeader {
  const parsed = parseHeader(header);
  if (parsed.timestamp === undefined) throw new SignatureError("missing timestamp");
  return { timestamp: parseTimestamp(parsed.timestamp), signatures: parsed.signatures };
}

export function computeSignature(secret: string, timestamp: number | string, rawBody: string | Buffer): string {
  return createHmac("sha256", secret).update(`${timestamp}.`, "utf8").update(rawBody).digest("hex");
}

function verifySignatures(
  rawBody: string | Buffer,
  timestamp: string,
  signatures: string[],
  secrets: string[],
  nowSec: number,
  toleranceSec: number,
): SignatureHeader {
  const signedAt = parseTimestamp(timestamp);
  if (!Number.isFinite(nowSec) || !Number.isFinite(toleranceSec) || toleranceSec < 0 ||
      Math.abs(nowSec - signedAt) > toleranceSec) {
    throw new SignatureError("timestamp outside tolerance");
  }
  let matched = false;
  for (const secret of secrets) {
    const expected = Buffer.from(computeSignature(secret, timestamp, rawBody), "hex");
    for (const signature of signatures) {
      // All signatures were validated as 32-byte hex strings during parsing.
      const equal = timingSafeEqual(expected, Buffer.from(signature, "hex"));
      matched = equal || matched;
    }
  }
  if (!matched) throw new SignatureError("signature mismatch");
  return { timestamp: signedAt, signatures };
}

export function verifyWebhook(
  rawBody: string | Buffer,
  header: string | undefined,
  secrets: string[],
  nowSec: number = Math.floor(Date.now() / 1000),
  toleranceSec: number = 300,
): SignatureHeader {
  if (typeof header !== "string" || !header) throw new SignatureError("missing Paygate-Signature header");
  const parsed = parseHeader(header);
  if (parsed.timestamp === undefined) throw new SignatureError("missing timestamp");
  return verifySignatures(rawBody, parsed.timestamp, parsed.signatures, secrets, nowSec, toleranceSec);
}

export function verifyReplayWebhook(
  rawBody: string | Buffer,
  timestamp: string | undefined,
  header: string | undefined,
  secrets: string[],
  nowSec: number = Math.floor(Date.now() / 1000),
  toleranceSec: number = 300,
): SignatureHeader {
  if (typeof timestamp !== "string") throw new SignatureError("missing X-Replay-Timestamp header");
  parseTimestamp(timestamp);
  if (typeof header !== "string" || !header) throw new SignatureError("missing X-Replay-Signature header");
  const parsed = parseHeader(header);
  if (parsed.timestamp !== undefined) throw new SignatureError("unexpected timestamp in X-Replay-Signature");
  return verifySignatures(rawBody, timestamp, parsed.signatures, secrets, nowSec, toleranceSec);
}
