cat > test/pay381.test.ts <<'EOF'
import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, readdirSync, rmSync } from "node:fs";
import { createServer } from "node:http";
import type { AddressInfo } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { decideStatus, EventError, parseEvent, processEvent } from "../src/refunds.ts";
import { buildApp } from "../src/server.ts";
import { Store } from "../src/store.ts";
import { computeSignature, SignatureError, verifyReplayWebhook, verifyWebhook } from "../src/verify.ts";

const SECRET = "whsec_pay381_test";
const OLD_SECRET = "whsec_pay381_old";
const POLICY = { auto_approve_max_minor: 500_000, auto_approve_currencies: ["INR"] };
const NOW = 1731920000;

function event(id: string, type = "refund.requested", data: Record<string, unknown> = {}) {
  return { event_id: id, type, created: NOW,
    data: { refund_id: "rf_381", payment_id: "pay_381", amount: 500_000, currency: "INR", ...data } };
}

function signed(body: string | Buffer, time = Math.floor(Date.now() / 1000), secret = SECRET) {
  return `t=${time},v1=${computeSignature(secret, time, body)}`;
}

// Snapshot every stored file, including raw events and audit entries.
function snapshot(dir: string, prefix = ""): Record<string, string> {
  const files: Record<string, string> = {};
  for (const entry of readdirSync(join(dir, prefix), { withFileTypes: true })) {
    const path = join(prefix, entry.name);
    if (entry.isDirectory()) Object.assign(files, snapshot(dir, path));
    else files[path] = readFileSync(join(dir, path)).toString("hex");
  }
  return files;
}

async function withApp(run: (ctx: {
  store: Store; dir: string; post: (body: string | Buffer, headers?: Record<string, string>) => Promise<Response>;
}) => Promise<void>) {
  const dir = mkdtempSync(join(tmpdir(), "pay381-"));
  const store = new Store(dir);
  const app = buildApp(store, { roles: {}, principals: {} }, POLICY,
    { webhook_secrets: [OLD_SECRET, SECRET], tolerance_s: 300, replay_tolerance_s: 86400 });
  const server = createServer((req, res) => void app(req, res));
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const url = `http://127.0.0.1:${(server.address() as AddressInfo).port}/webhooks/paygate`;
  try {
    await run({ store, dir, post: (body, headers = {}) => fetch(url, { method: "POST", headers, body }) });
  } finally {
    await new Promise<void>((resolve, reject) => server.close((err) => err ? reject(err) : resolve()));
    rmSync(dir, { recursive: true, force: true });
  }
}

test("signatures support rotation and require the exact raw body", () => {
  const body = JSON.stringify(event("evt_rotation"), null, 2) + "\n";
  const header = `${signed(body, NOW, "wrong")},v1=${computeSignature(SECRET, NOW, body)}`;
  assert.doesNotThrow(() => verifyWebhook(body, header, [OLD_SECRET, SECRET], NOW));
  assert.doesNotThrow(() => verifyWebhook(body, signed(body, NOW, OLD_SECRET), [OLD_SECRET, SECRET], NOW));
  assert.throws(() => verifyWebhook(JSON.stringify(JSON.parse(body)), header, [SECRET], NOW), SignatureError);
  assert.throws(() => verifyWebhook(body, header, [], NOW), SignatureError);
});

test("timestamp tolerance is inclusive and enforced in both directions", () => {
  const body = JSON.stringify(event("evt_window"));
  for (const offset of [-300, 300]) {
    assert.doesNotThrow(() => verifyWebhook(body, signed(body, NOW + offset), [SECRET], NOW));
  }
  for (const offset of [-301, 301]) {
    assert.throws(() => verifyWebhook(body, signed(body, NOW + offset), [SECRET], NOW), SignatureError);
  }
});

test("missing, malformed, and ambiguous signature headers fail closed", () => {
  const body = JSON.stringify(event("evt_malformed"));
  for (const header of [undefined, "", "v1=" + "a".repeat(64), `t=${NOW}`, `t=${NOW},v1=aa`,
    `t=${NOW},v1=${"A".repeat(64)}`, `t=${NOW}.5,v1=${"a".repeat(64)}`,
    `t=99999999999999999999,v1=${"a".repeat(64)}`, `${signed(body, NOW)},t=${NOW}`]) {
    assert.throws(() => verifyWebhook(body, header, [SECRET], NOW), SignatureError);
  }
});

test("replay verification checks fresh replay signatures with rotation and the same window", () => {
  const body = JSON.stringify(event("evt_replay_unit"));
  const sig = `v1=${computeSignature("wrong", NOW, body)},v1=${computeSignature(SECRET, NOW, body)}`;
  assert.doesNotThrow(() => verifyReplayWebhook(body, String(NOW), sig, [OLD_SECRET, SECRET], NOW));
  for (const offset of [-301, 301]) {
    const time = NOW + offset;
    assert.throws(() => verifyReplayWebhook(body, String(time),
      `v1=${computeSignature(SECRET, time, body)}`, [SECRET], NOW), SignatureError);
  }
  assert.throws(() => verifyReplayWebhook(body + " ", String(NOW), sig, [SECRET], NOW), SignatureError);
});

test("HTTP authentication failures never change any state", async () => withApp(async ({ post, dir }) => {
  const body = JSON.stringify(event("evt_forbidden"));
  const before = snapshot(dir);
  const now = Math.floor(Date.now() / 1000);
  const valid = signed(body, now);
  for (const headers of [
    {},
    { "paygate-signature": signed(body, now, "wrong") },
    { "paygate-signature": signed(body, now - 3600) },
    { "paygate-signature": valid, "x-replay-timestamp": String(now) },
    { "paygate-signature": valid, "x-replay-timestamp": "invalid", "x-replay-signature": "v1=" + "a".repeat(64) },
    { "paygate-signature": valid, "x-replay-timestamp": String(now), "x-replay-signature": "v1=" + "a".repeat(64) },
    { "paygate-signature": valid, "x-replay-timestamp": String(now - 3600),
      "x-replay-signature": `v1=${computeSignature(SECRET, now - 3600, body)}` },
    { "paygate-signature": valid, "x-replay-timestamp": String(now + 3600),
      "x-replay-signature": `v1=${computeSignature(SECRET, now + 3600, body)}` },
  ]) {
    const res = await post(body, headers);
    assert.equal(res.status, 401);
    await res.json();
    assert.deepEqual(snapshot(dir), before);
  }
  const invalidBody = "not JSON";
  const res = await post(invalidBody);
  assert.equal(res.status, 401); // Authenticate before parsing, even for invalid JSON.
  await res.json();
  assert.deepEqual(snapshot(dir), before);
}));

test("correctly signed invalid events return 400", async () => withApp(async ({ post }) => {
  for (const body of ["{", "null", "[]", "{}", JSON.stringify({ ...event("evt_bad"), created: "yesterday" }),
    JSON.stringify(event("evt_bad_amount", "refund.requested", { amount: -1 })),
    JSON.stringify(event("evt_bad_currency", "refund.requested", { currency: "" }))]) {
    const res = await post(body, { "paygate-signature": signed(body) });
    assert.equal(res.status, 400, body);
    await res.json();
  }
}));

test("HTTP duplicates preserve refunds, audit, state, and original raw events", async () => withApp(async ({ post, store, dir }) => {
  const original = JSON.stringify(event("evt_once"), null, 2);
  let res = await post(original, { "paygate-signature": signed(original) });
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { received: true, duplicate: false });
  const before = snapshot(dir);
  const changed = JSON.stringify(event("evt_once", "refund.requested", { amount: 900_000 }));
  const responses = await Promise.all(Array.from({ length: 4 }, () => post(changed, { "paygate-signature": signed(changed) })));
  for (res of responses) {
    assert.equal(res.status, 200);
    assert.deepEqual(await res.json(), { received: true, duplicate: true });
  }
  assert.deepEqual(snapshot(dir), before);
  assert.equal(store.listRefunds().length, 1);
  const restarted = new Store(dir);
  assert.equal(processEvent(restarted, POLICY, parseEvent(changed)).outcome, "duplicate");
  assert.deepEqual(snapshot(dir), before);
  res = await post(original, { "paygate-signature": signed(original, Math.floor(Date.now() / 1000), "wrong") });
  assert.equal(res.status, 401); // Duplicates must still authenticate.
  await res.json();
  assert.deepEqual(snapshot(dir), before);
}));

test("replays ignore original authentication and deduplicate with normal deliveries", async () => withApp(async ({ post, dir }) => {
  const body = JSON.stringify(event("evt_replay_http"));
  const now = Math.floor(Date.now() / 1000);
  const headers = { "x-replay-timestamp": String(now),
    "x-replay-signature": `v1=${computeSignature(SECRET, now, body)}` };
  let res = await post(body, headers); // No original signature needed.
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { received: true, duplicate: false });
  const before = snapshot(dir);
  res = await post(body, { ...headers, "paygate-signature": "invalid original signature" });
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { received: true, duplicate: true });
  res = await post(body, { "paygate-signature": signed(body) });
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { received: true, duplicate: true });
  assert.deepEqual(snapshot(dir), before);
}));

test("unknown event types are acknowledged and deduplicated without refunds", async () => withApp(async ({ post, store, dir }) => {
  const body = JSON.stringify({ event_id: "evt_unknown", created: NOW, type: "payment.updated", data: {} });
  let res = await post(body, { "paygate-signature": signed(body) });
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { received: true, duplicate: false });
  assert.equal(store.listRefunds().length, 0);
  const before = snapshot(dir);
  res = await post(body, { "paygate-signature": signed(body) });
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { received: true, duplicate: true });
  assert.deepEqual(snapshot(dir), before);
}));

test("cancellation duplicates do not repeat audits or mutations", async () => withApp(async ({ store, dir }) => {
  for (const amount of [500_000, 500_001]) {
    const refund_id = `rf_${amount}`;
    processEvent(store, POLICY, event(`evt_req_${amount}`, "refund.requested", { amount, refund_id }));
    const cancel = event(`evt_cancel_${amount}`, "refund.cancelled", { refund_id });
    processEvent(store, POLICY, cancel);
    assert.equal(store.findByPaygateId(refund_id)[0].status, amount === 500_000 ? "auto_approved" : "cancelled");
    const before = snapshot(dir);
    assert.equal(processEvent(store, POLICY, cancel).outcome, "duplicate");
    assert.deepEqual(snapshot(dir), before);
  }
}));

test("failed processing does not mark an event processed", async () => withApp(async ({ store }) => {
  assert.throws(() => processEvent(store, POLICY, event("evt_retry", "refund.requested", { amount: 0 })), EventError);
  assert.equal(store.isProcessed("evt_retry"), false);
  assert.equal(processEvent(store, POLICY, event("evt_retry")).outcome, "processed");
}));

test("event IDs matching object prototype properties are processed exactly once", async () => withApp(async ({ store, dir }) => {
  for (const id of ["constructor", "toString", "__proto__"]) {
    assert.equal(processEvent(store, POLICY, event(id)).outcome, "processed");
    assert.equal(processEvent(new Store(dir), POLICY, event(id)).outcome, "duplicate");
  }
}));

test("configured policy follows Dana's inclusive INR-only threshold", () => {
  const policy = JSON.parse(readFileSync(new URL("../config/refunds.json", import.meta.url), "utf8"));
  assert.equal(policy.auto_approve_max_minor, 500_000);
  assert.deepEqual(policy.auto_approve_currencies, ["INR"]);
  assert.equal(decideStatus(policy, 499_999, "INR"), "auto_approved");
  assert.equal(decideStatus(policy, 500_000, "INR"), "auto_approved");
  assert.equal(decideStatus(policy, 500_001, "INR"), "pending_review");
  assert.equal(decideStatus(policy, 1, "USD"), "pending_review");
});
